'use strict';
const $ = s => document.querySelector(s);
const world = $('#world'), field = $('#bottle-field'), summon = $('#summon');
const quotes = ['你有梦想，我有大水。','格局打开，瓶盖也打开。','别人上热搜，我上水位。','这不是普通的水，这是流动的排面。','水可以不喝，气氛必须拉满。','流量会退潮，水不会。','先别分析，先吨吨吨。','大水没有瓶颈，只有瓶盖。','你负责抽象，我负责补水。','今天的含水量，超乎你的想象。','我不生产梗，我只是大水的搬运工。','这波不是浪，是大水。'];
const realQuotes = [
 {text:'不付费的内容都是耍流氓！',source:'新榜采访 · 2016-11-26',url:'https://www.newrank.cn/article/detail/2979',context:'谈对内容付费的看法。'},
 {text:'我不在意这些猜疑和误解',source:'证券时报采访／每日经济新闻转载 · 2019-06-05',url:'https://www.sohu.com/a/318800539_115362',context:'回应外界对他及项目的标签，原回答节选。'},
 {text:'这个世界正在改变',source:'证券时报采访／每日经济新闻转载 · 2019-06-05',url:'https://www.sohu.com/a/318800539_115362',context:'谈与巴菲特交流及年轻一代正在做的事情，原回答节选。'},
 {text:'这比其他香蕉好吃多了，味道真的很棒。',source:'法新社报道／东方日报转载 · 2024-11-29',url:'https://www.orientaldaily.com.my/news/buzz/2024/11/29/696484',context:'在香港活动上吃下《喜剧演员》中的香蕉后，报道所载中文译文。'}
];
const originalCount = quotes.length;
quotes.push(...realQuotes.map(q=>q.text));
quotes.push('小水解渴，大水撑场。','生活可以没头绪，瓶盖一定要拧紧。','别急着上岸，先看看哪瓶是你的水。','别人研究风口，我研究瓶口。','今天不画饼，今天画水圈。','人生没有标准答案，但水瓶有刻度。','喝水归喝水，别把瓶子当人生导师。','事情可以慢慢想，水不用一口喝完。','这不是水太多，是杯子格局太小。','不跟风，跟着自己的水流走。','你问我有什么规划？先把瓶盖打开。','没有什么是一瓶大水解决不了的。除了想再来一瓶。');
function quoteMeta(i){return i>=originalCount&&i<originalCount+realQuotes.length?realQuotes[i-originalCount]:null}
let quoteMode='mix',lastQuote=-1;
const storageKey = 'water-theory-quotes-v1';
let collected = new Set();
try { const stored=JSON.parse(localStorage.getItem(storageKey)||'[]'); if(Array.isArray(stored)) collected=new Set(stored.filter(n=>Number.isInteger(n)&&n>=0&&n<quotes.length)); } catch {}
let level=0, holding=false, paused=matchMedia('(prefers-reduced-motion: reduce)').matches, sound=false, audio, holdTimer, toastTimer, floodCooldown=0, bottleId=0, quoteCursor=0;
function updateCollection(){ $('#collection-count').textContent=collected.size; $('#collection-total').textContent=`${collected.size} / ${quotes.length}`; const list=$('#quote-list');list.replaceChildren();quotes.forEach((q,i)=>{const row=document.createElement('div');row.className='quote-row'+(collected.has(i)?'':' locked');const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');const content=document.createElement('div');const text=document.createElement('p');text.textContent=collected.has(i)?q:'还没捞到，去点点漂浮的水瓶。';content.append(text);if(collected.has(i)){const meta=quoteMeta(i);const tag=document.createElement('small');tag.className='quote-type';tag.textContent=meta?'孙哥原话 · 节选':'原创玩梗';content.append(tag);if(meta){const link=document.createElement('a');link.href=meta.url;link.target='_blank';link.rel='noopener noreferrer';link.className='source-link';link.textContent='查看出处 ↗';content.append(link)}}row.append(num,content);list.append(row)}); }
function persist(){try{localStorage.setItem(storageKey,JSON.stringify([...collected]))}catch{}}
function showToast(text,sub='原创梗句 · 不是真人发言'){const t=$('#toast');t.replaceChildren();t.append(document.createTextNode(text));const small=document.createElement('small');small.textContent=sub;t.append(small);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3000)}
function playDrop(){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)(); if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.setValueAtTime(650+Math.random()*200,audio.currentTime);o.frequency.exponentialRampToValueAtTime(160,audio.currentTime+.16);g.gain.setValueAtTime(.065,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.23);o.start();o.stop(audio.currentTime+.25)}catch{sound=false;renderSound()}}
function splash(x,y){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<10;i++){const d=document.createElement('i');d.className='droplet';d.style.left=x+'px';d.style.top=y+'px';d.style.setProperty('--dx',(Math.random()-.5)*170+'px');d.style.setProperty('--dy',(Math.random()-.6)*160+'px');$('#fx').append(d);setTimeout(()=>d.remove(),800)}}
function popQuote(x,y){const all=quotes.map((_,i)=>i),real=all.filter(i=>quoteMeta(i)),memes=all.filter(i=>!quoteMeta(i));let pool=quoteMode==='real'?real:quoteMode==='meme'?memes:(Math.random()<.5?real:memes);const fresh=pool.filter(i=>!collected.has(i));if(fresh.length)pool=fresh;const other=pool.filter(i=>i!==lastQuote);if(other.length)pool=other;const n=pool[Math.floor(Math.random()*pool.length)];lastQuote=n;collected.add(n);persist();updateCollection();const meta=quoteMeta(n);showToast(quotes[n],meta?'孙哥原话 · '+meta.source:'原创梗句 · 不是真人发言');if(meta){const a=document.createElement('a');a.href=meta.url;a.target='_blank';a.rel='noopener noreferrer';a.className='toast-source';a.textContent='查看原文出处 ↗';$('#toast').append(a);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}setLevel(level+7);splash(x,y);playDrop()}
function addBottle(x,y,size,angle,extra=false){const el=document.createElement('button');el.className='bottle';el.setAttribute('aria-label',`水瓶 ${++bottleId}：点击收集梗句，拖动改变位置`);el.style.setProperty('--size',size+'px');el.style.setProperty('--angle',angle+'deg');el.style.setProperty('--delay',-Math.random()*6+'s');el.style.left=x+'px';el.style.top=y+'px';el.innerHTML='<img src="assets/bottle-dashui.webp" alt="" draggable="false">';el.dataset.extra=String(extra);field.append(el);let drag=null,suppressClick=false;
el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=el.getBoundingClientRect(),w=world.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:parseFloat(el.style.left),startY:parseFloat(el.style.top),moved:false};el.setPointerCapture(e.pointerId);el.classList.add('dragging');suppressClick=false});
el.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>6)drag.moved=true;if(drag.moved){el.style.left=Math.max(-size*.25,Math.min(world.clientWidth-size*.75,drag.startX+dx))+'px';el.style.top=Math.max(100,Math.min(world.clientHeight-size*1.7,drag.startY+dy))+'px'}});
function finish(e){if(!drag||e.pointerId!==drag.id)return;suppressClick=drag.moved;drag=null;el.classList.remove('dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId)}
el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',e=>{finish(e);suppressClick=true});el.addEventListener('lostpointercapture',()=>{drag=null;el.classList.remove('dragging')});
el.addEventListener('click',e=>{if(suppressClick){suppressClick=false;return}const r=el.getBoundingClientRect(),w=world.getBoundingClientRect();popQuote(r.x-w.x+r.width/2,r.y-w.y+r.height/2)});return el}
function layoutBottles(){field.replaceChildren();const w=world.clientWidth,h=world.clientHeight,m=w<600;const positions=m?[[.01,.46,65,-22],[.8,.49,72,21],[.05,.73,47,30],[.81,.72,46,-18],[.69,.16,37,28]]:[[.03,.20,85,-24],[.28,.34,74,22],[.88,.17,88,22],[.91,.63,84,-25],[.22,.68,95,28],[.70,.66,72,-15],[.62,.13,48,-25]];positions.forEach(([x,y,s,a])=>addBottle(w*x,h*y,m?s:s*Math.min(1.3,w/1300),a));}
function setLevel(n){level=Math.max(0,Math.min(100,n));$('#water-value').innerHTML=Math.floor(level)+'<small>%</small>';$('#meter-fill').style.width=level+'%';$('#water').style.height=level*.62+'%';$('#water-status').textContent=level>=90?'水位已满，抽象拉满。':level>=60?'有点离谱，继续加水。':level>=25?'水花渐起，好戏开场。':'风平浪静，暗藏大水。';}
function startHold(){if(holding||$('dialog[open]'))return;holding=true;summon.classList.add('active');summon.querySelector('span').firstChild.textContent='大水正在赶来';let ticks=0;const tick=()=>{setLevel(level+3);ticks++;if(ticks%4===0&&field.children.length<18){const w=world.clientWidth;addBottle(20+Math.random()*(w-100),120+Math.random()*(world.clientHeight*.5),w<600?35+Math.random()*25:45+Math.random()*50,(Math.random()-.5)*90,true);playDrop()}if(level>=100&&Date.now()-floodCooldown>5000){floodCooldown=Date.now();showToast('大水来了，建议先把瓶盖拧紧。','大水值已满 · 松手慢慢退潮');splash(world.clientWidth/2,world.clientHeight*.35)}};tick();holdTimer=setInterval(tick,140)}
function stopHold(){if(!holding)return;holding=false;clearInterval(holdTimer);summon.classList.remove('active');summon.querySelector('span').firstChild.textContent='按住，召唤大水'}
summon.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();summon.setPointerCapture(e.pointerId);startHold()});['pointerup','pointercancel','lostpointercapture'].forEach(name=>summon.addEventListener(name,stopHold));
summon.addEventListener('click',e=>{if(e.detail===0){setLevel(level+18);showToast('再来一瓶，抽象加倍。','用空格键持续召唤大水');playDrop()}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!$('dialog[open]')&&(!e.target.closest('button,a,input,textarea')||e.target===summon)){e.preventDefault();startHold()}});document.addEventListener('keyup',e=>{if(e.code==='Space'){e.preventDefault();stopHold()}});window.addEventListener('blur',stopHold);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopHold()});
setInterval(()=>{if(!holding&&!paused&&!document.hidden&&level>0)setLevel(level-.6)},250);
function renderPause(){world.classList.toggle('paused',paused);$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-pressed',String(paused));$('#pause').setAttribute('aria-label',paused?'继续漂浮':'暂停漂浮')}
$('#pause').addEventListener('click',()=>{paused=!paused;renderPause()});function renderSound(){$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').setAttribute('aria-label',sound?'关闭水滴音效':'开启水滴音效');$('.sound-slash').hidden=sound}$('#sound').addEventListener('click',()=>{sound=!sound;renderSound();if(sound)playDrop()});
$('#reset').addEventListener('click',()=>{stopHold();setLevel(0);layoutBottles();$('#fx').replaceChildren();$('#toast').classList.remove('show');showToast('风平浪静，重开一瓶。','水世界已重置 · 收藏仍在')});
function openDialog(d){stopHold();d.showModal()}$('#open-collection').addEventListener('click',()=>openDialog($('#collection')));$('#about-open').addEventListener('click',()=>openDialog($('#about')));document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close').forEach(b=>b.addEventListener('click',()=>d.close()));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(layoutBottles,180)});layoutBottles();updateCollection();renderPause();renderSound();setLevel(0);
const floatingText=[...document.querySelectorAll('.orbit-quotes>span')];
function renderQuoteMode(){document.querySelectorAll('[data-quote-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quoteMode===quoteMode)));const memeIndexes=quotes.map((_,i)=>i).filter(i=>!quoteMeta(i));floatingText.forEach((el,i)=>{const real=quoteMode==='real'||(quoteMode==='mix'&&i<3);const q=real?realQuotes[i%realQuotes.length]:null;el.replaceChildren(document.createTextNode(q?q.text:quotes[memeIndexes[(i*5+3)%memeIndexes.length]]));const label=document.createElement('small');label.textContent=q?'孙哥原话 · 有出处':'原创玩梗';el.append(label)});$('#quote-hint').textContent=quoteMode==='real'?'点瓶子，听听孙哥原话。':quoteMode==='meme'?'点瓶子，捞一个原创梗。':'点瓶子，原话和梗都来点。'}
document.querySelectorAll('[data-quote-mode]').forEach(b=>b.addEventListener('click',()=>{quoteMode=b.dataset.quoteMode;renderQuoteMode()}));renderQuoteMode();
